// fix-health-app-v2.4.14.cjs — Family Health Track v2.4.14 one-step fix
// Run from the project root (the folder with package.json) with:
//   node fix-health-app-v2.4.14.cjs
// Requires v2.4.13 already applied (run the earlier scripts first if you
// have not run them yet). What it does:
//   1. Backs up each changed file to <file>.bak (first run only)
//   2. Applies the v2.4.14 fix — the BMI card now reads the latest BMI
//      RECORD first (then the patient profile, then your profile), so it
//      no longer says 'no record' when BMI records exist; the admin
//      header BMI badge does the same for a patient; Trends passes the
//      age to the BMI calculation and uses the family member's own age;
//      family-member view traps fixed (card, age, add-form prefill,
//      saved name and waist-risk gender now use the member, not the
//      owner)
//   3. Runs npm install, typecheck (tsc), tests (vitest) and build
// Safe to run twice: files already matching the new content are skipped.
// It does NOT touch your data, your Firebase project, or git.
// NOTE: this version does NOT change firestore.rules — no Console step
// is needed for the rules.
const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const VERSION = '2.4.14';
const FILES = [
  {
    "path": "package.json",
    "b64": ""
  },
  {
    "path": "src/components/modules/BMIModule.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/admin/AdminPatientDetail.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/TrendsOverview.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/VersionHistoryModal.tsx",
    "b64": ""
  },
  {
    "path": "src/constants/version.ts",
    "b64": "ZXhwb3J0IGNvbnN0IENVUlJFTlRfU1lTVEVNX1ZFUlNJT04gPSAndjIuNC4xNCc7Cg=="
  }
];

const norm = (s) => String(s).replace(/\r\n/g, '\n');
let applied = 0, skipped = 0, failed = 0;
const failures = [];
function run(cmd, args, label) {
  console.log('  $ ' + cmd + ' ' + args.join(' '));
  const r = spawnSync(cmd, args, { stdio: 'inherit', shell: process.platform === 'win32' });
  if (r.error || r.status !== 0) {
    console.log('[FAIL] ' + label + ' (exit ' + (r.status ?? r.error) + ')');
    return false;
  }
  console.log('[OK] ' + label);
  return true;
}
function main() {
  console.log('Family Health Track fix — v' + VERSION);
  console.log('Project folder: ' + process.cwd());
  const pkgPath = path.join(process.cwd(), 'package.json');
  if (!fs.existsSync(pkgPath)) {
    console.log('[ERROR] package.json not found here. Run this script from the project root (the folder with package.json).');
    process.exit(1);
  }
  let pkg;
  try { pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8')); } catch (e) {
    console.log('[ERROR] package.json could not be read: ' + e.message);
    process.exit(1);
  }
  if (pkg.name !== 'family-health-track') {
    console.log('[ERROR] This does not look like the Family Health Track project (package name: ' + pkg.name + '). Stopping.');
    process.exit(1);
  }
  if (String(pkg.version) === '2.4.12') {
    console.log('[ERROR] This project is still v2.4.12. Run fix-health-app-v2.4.13.cjs first, then run this script again.');
    process.exit(1);
  }
  if (['2.4.6', '2.4.7', '2.4.8', '2.4.9', '2.4.10', '2.4.11'].includes(String(pkg.version))) {
    console.log('[ERROR] This project is still v' + pkg.version + '. Run the v2.4.9, v2.4.10, v2.4.11, v2.4.12 and v2.4.13 scripts first (in order), then run this script again.');
    process.exit(1);
  }
  if (!['2.4.13', '2.4.14'].includes(String(pkg.version))) {
    console.log('[ERROR] Unexpected project version ' + pkg.version + ' (expected 2.4.13). Stopping — ask for help before running this.');
    process.exit(1);
  }
  for (const f of FILES) {
    const dest = path.join(process.cwd(), ...f.path.split('/'));
    const next = Buffer.from(f.b64, 'base64').toString('utf8');
    try {
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      if (fs.existsSync(dest) && norm(fs.readFileSync(dest, 'utf8')) === norm(next)) {
        console.log('[SKIP] already applied: ' + f.path);
        skipped++;
        continue;
      }
      if (fs.existsSync(dest) && !fs.existsSync(dest + '.bak')) {
        fs.copyFileSync(dest, dest + '.bak');
      }
      fs.writeFileSync(dest, next, 'utf8');
      console.log('[OK] applied: ' + f.path);
      applied++;
    } catch (e) {
      console.log('[FAIL] ' + f.path + ': ' + e.message);
      failed++;
      failures.push(f.path + ': ' + e.message);
    }
  }
  console.log('');
  console.log('Applied ' + applied + ' | Already applied ' + skipped + ' | Failed ' + failed);
  if (failed > 0) {
    console.log('Failures: ' + failures.join(' ; '));
    console.log('Stopping before checks. Your .bak backups are next to the originals.');
    process.exit(1);
  }
  console.log('');
  console.log('--- checks (npm install, typecheck, tests, build) ---');
  const okInstall = run('npm', ['install', '--no-audit', '--no-fund'], 'npm install');
  const okLint = run('npx', ['tsc', '--noEmit'], 'typecheck (tsc --noEmit)');
  const okTest = run('npx', ['vitest', 'run'], 'tests (vitest run)');
  const okBuild = run('npm', ['run', 'build'], 'build (vite build)');
  if (!okInstall || !okLint || !okTest || !okBuild) {
    console.log('');
    console.log('[DONE WITH ERRORS] Files were updated, but a check failed above.');
    console.log('Do NOT deploy yet. Ask for help and include the error lines above.');
    process.exit(1);
  }
  console.log('');
  console.log('[DONE] v' + VERSION + ' applied. Applied ' + applied + ' | Already applied ' + skipped + ' | Failed 0');
  console.log('');
  console.log('NEXT STEPS (အဆင့်လိုက် လုပ်ပါ):');
  console.log('  1. App ကို push / deploy လုပ်ပါ (git push လုပ်ပြီး Cloudflare က');
  console.log('     ပြန် deploy ပါလိမ့်မယ်)။');
  console.log('     ဒီ version မှာ firestore.rules အပြောင်းအလဲ မရှိပါ —');
  console.log('     Firebase Console မှာ ဘာမှ လုပ်စရာ မလိုပါ။');
  console.log('  2. ဖုန်းမှာ hard-refresh တစ်ခါ လုပ်ပါ။');
  console.log('     Version History မှာ v2.4.14 ပြရပါမယ်။');
  console.log('  3. ဖုန်းမှာ ဒါတွေ စစ်ပါ:');
  console.log('     (1) Profile မှာ အရပ်/အလေးချိန် မရှိတဲ့ လူနာအတွက် BMI ကတ်က');
  console.log('         BMI မှတ်တမ်းထဲက BMI ကို ပြရပါမယ် —');
  console.log("         'မှတ်တမ်း မရှိသေးပါ' လို့ မပြရပါ။");
  console.log('     (2) မိသားစုဝင် ရွေးထားရင် အဲဒီဝင်ရဲ့ ကိုယ်ပိုင် BMI/အသက်');
  console.log('         ပြရပါမယ်။ မိသားစုဝင်အတွက် မှတ်တမ်းအသစ် ထည့်ရင်');
  console.log('         form မှာ အဲဒီဝင်ရဲ့ တန်ဖိုးတွေ (ပိုင်ရှင်ရဲ့');
  console.log('         တန်ဖိုးတွေ မဟုတ်ပါ) ပြရပါမယ်။');
  console.log('     (3) Admin အနေနဲ့ ကြည့်ရင် Profile မှာ အရပ်/အလေးချိန်');
  console.log('         မရှိပေမယ့် BMI မှတ်တမ်း ရှိတဲ့ လူနာအတွက် အပေါ်က');
  console.log('         BMI badge ပေါ်ရပါမယ်။');
  console.log('     (4) တစ်ခုတည်းသော BMI မှတ်တမ်းကို ဖျက်လိုက်ရင် Profile');
  console.log("         တန်ဖိုးတွေ ရှိရင် အဲဒါတွေ ပြရပါမယ်၊ ဘာမှ မရှိရင်သာ");
  console.log("         'မှတ်တမ်း မရှိသေးပါ' လို့ မှန်မှန်ကန်ကန် ပြရပါမယ်။");
}
main();
